// SetStorage 注入统一存储实例（bootstrap 调用）。
// 回归要点：此前 chunk（DataPath=./data）与 share（./data/uploads）两个懒加载
// 单例路径基不一致，分片合并写入 `data/uploads/<rel>`、下载却找
// `data/uploads/uploads/<rel>` → 跨 handler 写读必然 500。
func SetStorage(st storage.StorageInterface) {
	storageSvc = st
}

func getStorageService() storage.StorageInterface {
	if storageSvc == nil {
		storageSvc = storage.NewStorageService(&storage.StorageConfig{
			Type:     storage.StorageTypeLocal,
			DataPath: defaultStoragePath,
			BaseURL:  defaultBaseURL,
		})
	}
	return storageSvc
}

func getShareService() *shareService.Service {
	if shareSvc == nil {
		shareSvc = shareService.NewService(defaultBaseURL, getStorageService())
	}
	return shareSvc
}

// ChunkUploadInit .
// @router /chunk/upload/init/ [POST]
func ChunkUploadInit(ctx context.Context, c *app.RequestContext) {
	// 上传闸门：匿名总开关 + 登录要求（chunk 为纯匿名通道，服务端 enforce）
	if err := gate.CheckUploadAllowed(nil); err != nil {
		resp.NewTypedError(c, err)
		return
	}
	if err := gate.CheckUploadLogin(nil); err != nil {
		resp.NewTypedError(c, err)
		return
	}

	var err error
	var req chunkmodel.ChunkUploadInitReq
	err = c.BindAndValidate(&req)
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": err.Error(),
		})
		return
	}
	// 匿名 per-IP 日配额（分片通道按整文件申报大小计数）
	if err := gate.CheckAnonymousQuota(ctx, middleware.ClientIP(c), req.FileSize); err != nil {
		resp.NewTypedError(c, err)
		return
	}

	// 参数验证
	if req.FileName == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "文件名不能为空",
		})
		return
	}
	if req.FileSize <= 0 {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "文件大小必须大于0",
		})
		return
	}
	if req.ChunkSize <= 0 {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "分片大小必须大于0",
		})
		return
	}

	// 生成上传ID
	uploadID := req.FileHash
	if uploadID == "" {
		uploadID = uuid.New().String()
	}

	// 检查快速上传：如果文件已存在，直接返回分享代码
	if req.FileHash != "" {
		shareCode, err := getChunkService().CheckQuickUpload(ctx, req.FileHash, req.FileSize)
		if err == nil && shareCode != "" {
			resp := &chunkmodel.ChunkUploadInitResp{
				Code:    200,
				Message: "文件已存在，快速上传成功",
				Data: &chunkmodel.ChunkUploadInitData{
					UploadID:      uploadID,
					ChunkSize:     fmt.Sprintf("%d", req.ChunkSize),
					TotalChunks:   fmt.Sprintf("%d", req.TotalChunks),
					IsQuickUpload: true,
					ShareCode:     shareCode,
				},
			}
			c.JSON(consts.StatusOK, resp)
			return
		}
	}

	// 初始化上传
	initReq := &chunkService.InitiateUploadReq{
		UploadID:    uploadID,
		FileName:    req.FileName,
		TotalChunks: int(req.TotalChunks),
		FileSize:    req.FileSize,
		ChunkSize:   int(req.ChunkSize),
		OwnerIP:     middleware.ClientIP(c),
	}
	if uid, exists := c.Get("user_id"); exists {
		if uidUint, ok := uid.(uint); ok {
			initReq.UserID = &uidUint
		}
	}

	result, err := getChunkService().InitiateUpload(ctx, initReq)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "初始化上传失败: " + err.Error(),
		})
		return
	}

	resp := &chunkmodel.ChunkUploadInitResp{
		Code:    200,
		Message: "初始化成功",
		Data: &chunkmodel.ChunkUploadInitData{
			UploadID:      result.UploadID,
			ChunkSize:     fmt.Sprintf("%d", result.ChunkSize),
			TotalChunks:   fmt.Sprintf("%d", result.TotalChunks),
			IsQuickUpload: false,
		},
	}

	c.JSON(consts.StatusOK, resp)
}

// ChunkUpload .
// @router /chunk/upload/chunk/:upload_id/:chunk_index [POST]
func ChunkUpload(ctx context.Context, c *app.RequestContext) {
	var err error

	// 获取路径参数
	uploadID := c.Param("upload_id")
	chunkIndexStr := c.Param("chunk_index")

	if uploadID == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "上传ID不能为空",
		})
		return
	}

	chunkIndex, err := strconv.Atoi(chunkIndexStr)
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "分片索引格式错误",
		})
		return
	}

	// 获取上传的文件
	file, err := c.FormFile("chunk")
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "请上传分片文件",
		})
		return
	}

	// 读取文件内容
	src, err := file.Open()
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "读取文件失败: " + err.Error(),
		})
		return
	}
	defer func() { _ = src.Close() }()

	// 读取文件数据到内存
	data := make([]byte, file.Size)
	_, err = io.ReadFull(src, data)
	if err != nil && err != io.EOF && err != io.ErrUnexpectedEOF {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "读取文件内容失败: " + err.Error(),
		})
		return
	}

	// 计算分片哈希
	hash := md5.Sum(data)
	chunkHash := hex.EncodeToString(hash[:])

	// 保存分片到存储
	err = getStorageService().SaveChunk(ctx, uploadID, chunkIndex, data)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "保存分片失败: " + err.Error(),
		})
		return
	}

	// 记录分片上传信息
	uploadReq := &chunkService.UploadChunkReq{
		UploadID:   uploadID,
		ChunkIndex: chunkIndex,
		ChunkHash:  chunkHash,
		ChunkSize:  int(file.Size),
	}

	result, err := getChunkService().UploadChunk(ctx, uploadReq)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "记录分片信息失败: " + err.Error(),
		})
		return
	}

	resp := &chunkmodel.ChunkUploadResp{
		Code:    200,
		Message: "分片上传成功",
		Data: &chunkmodel.ChunkUploadData{
			ChunkIndex: int32(result.ChunkIndex),
			ChunkHash:  result.ChunkHash,
		},
	}

	c.JSON(consts.StatusOK, resp)
}

// ChunkUploadStatus .
// @router /chunk/upload/status/:upload_id [GET]
func ChunkUploadStatus(ctx context.Context, c *app.RequestContext) {
	var err error

	// 获取上传ID
	uploadID := c.Param("upload_id")
	if uploadID == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "上传ID不能为空",
		})
		return
	}

	// 获取上传信息
	info, err := getChunkService().GetUploadInfo(ctx, uploadID)
	if err != nil {
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    404,
			"message": "上传记录不存在",
		})
		return
	}

	// 获取已上传分片索引
	uploadedIndexes, err := getChunkService().GetUploadedChunkIndexes(ctx, uploadID)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "获取上传进度失败: " + err.Error(),
		})
		return
	}

	// 计算进度
	var progress float64
	if info.TotalChunks > 0 {
		progress = float64(len(uploadedIndexes)) / float64(info.TotalChunks) * 100
	}

	// 确定状态
	status := "uploading"
	if len(uploadedIndexes) == info.TotalChunks {
		status = "completed"
	} else if len(uploadedIndexes) == 0 {
		status = "pending"
	}

	// 转换索引数组
	uploadedIndexes32 := make([]int32, len(uploadedIndexes))
	for i, idx := range uploadedIndexes {
		uploadedIndexes32[i] = int32(idx)
	}

	resp := &chunkmodel.ChunkUploadStatusResp{
		Code:    200,
		Message: "获取成功",
		Data: &chunkmodel.ChunkUploadStatusData{
			UploadID:        info.UploadID,
			TotalChunks:     int32(info.TotalChunks),
			UploadedChunks:  int32(len(uploadedIndexes)),
			UploadedIndexes: uploadedIndexes32,
			Progress:        int32(progress),
			Status:          status,
		},
	}

	c.JSON(consts.StatusOK, resp)
}

// ChunkUploadComplete .
// @router /chunk/upload/complete/:upload_id [POST]
func ChunkUploadComplete(ctx context.Context, c *app.RequestContext) {
	var err error

	// 获取上传ID
	uploadID := c.Param("upload_id")
	if uploadID == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "上传ID不能为空",
		})
		return
	}

	// 解析请求参数
	var req chunkmodel.ChunkUploadCompleteReq
	err = c.BindAndValidate(&req)
	if err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": err.Error(),
		})
		return
	}

	// 获取上传信息
	info, err := getChunkService().GetUploadInfo(ctx, uploadID)
	if err != nil {
		c.JSON(consts.StatusNotFound, map[string]interface{}{
			"code":    404,
			"message": "上传记录不存在",
		})
		return
	}

	// 归属校验（治理）：控制记录已记 OwnerIP/UserID 时，仅归属方可 Complete，
	// 防猜中 uploadID 劫持他人上传会话（老数据 OwnerIP 为空跳过，保持兼容）
	if info.OwnerIP != "" && info.OwnerIP != middleware.ClientIP(c) {
		sameUser := false
		if info.UserID != nil {
			if uid, exists := c.Get("user_id"); exists {
				if uidUint, ok := uid.(uint); ok && uidUint == *info.UserID {
					sameUser = true
				}
			}
		}
		if !sameUser {
			c.JSON(consts.StatusForbidden, map[string]interface{}{
				"code":    errcode.CodeForbidden,
				"message": "无权操作该上传会话",
			})
			return
		}
	}

	// 检查所有分片是否已上传
	uploadedIndexes, err := getChunkService().GetUploadedChunkIndexes(ctx, uploadID)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "检查上传状态失败: " + err.Error(),
		})
		return
	}

	if len(uploadedIndexes) < info.TotalChunks {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": fmt.Sprintf("还有 %d 个分片未上传", info.TotalChunks-len(uploadedIndexes)),
		})
		return
	}

	// 合并分片
	now := time.Now()
	fileExt := filepath.Ext(info.FileName)
	uuidFileName := uuid.New().String() + fileExt

	relativePath := filepath.Join(
		"uploads",
		now.Format("2006"),
		now.Format("01"),
		now.Format("02"),
		uuidFileName,
	)

	err = getStorageService().MergeChunks(ctx, uploadID, info.TotalChunks, relativePath)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "合并分片失败: " + err.Error(),
		})
		return
	}

	// 计算合并后整文件 SHA-256（秒传依据；此前恒以 uploadID 冒充 file_hash）。
	// 回归要点：必须经注入的 storage 实例读取（与合并写入同基 + resolveLocal
	// 历史布局兼容），不能硬编码 "./data"——统一存储实例后基已变，硬编码读不到
	// → file_hash 恒空 → 分片通道秒传永不命中。
	var head []byte
	fileHash := ""
	var actualSize int64
	if rc, fsize, rerr := getStorageService().GetFileReader(ctx, relativePath); rerr == nil {
		actualSize = fsize
		// 先读 512 字节做魔数复检，再以 MultiReader 把头部拼回流算整文件哈希
		//（ReadCloser 不保证可 Seek，不能回卷）
		head = readHeadFrom(rc, 512)
		fileHash, _ = utils.HashReader(io.MultiReader(bytes.NewReader(head), rc))
		_ = rc.Close()
	}
	if fileHash == "" {
		// 哈希失败不阻断分享创建（仅失去秒传能力），记空
		fmt.Println("计算文件哈希失败（分享创建继续，仅失去秒传能力）")
	}

	// 魔数+扩展名复检（首分片可能绕过 init 校验）
	if head != nil {
		if err := utils.CheckUploadContent(info.FileName, head); err != nil {
			_ = getStorageService().DeleteFile(ctx, relativePath)
			_ = getChunkService().DeleteUpload(ctx, uploadID)
			c.JSON(consts.StatusBadRequest, map[string]interface{}{
				"code":    errcode.CodeFileTypeDenied,
				"message": err.Error(),
			})
			return
		}
	}

	// 完整性复查：合并后实际大小 vs 上限/申报（修复：init 自报 FileSize 从未被复核，
	// 可申报 1KB 实传任意大文件绕过 max_file_size；申报不符说明分片丢失或被篡改）
	if actualSize > 0 {
		if maxFile := utils.GetMaxFileSize(); maxFile > 0 && actualSize > maxFile {
			_ = getStorageService().DeleteFile(ctx, relativePath)
			_ = getChunkService().DeleteUpload(ctx, uploadID)
			c.JSON(consts.StatusBadRequest, map[string]interface{}{
				"code":    errcode.CodeTooLarge,
				"message": fmt.Sprintf("合并后文件大小 %d 字节超过上限 %d 字节", actualSize, maxFile),
			})
			return
		}
		if info.FileSize > 0 && actualSize != info.FileSize {
			_ = getStorageService().DeleteFile(ctx, relativePath)
			_ = getChunkService().DeleteUpload(ctx, uploadID)
			c.JSON(consts.StatusBadRequest, map[string]interface{}{
				"code":    errcode.CodeChunkInvalid,
				"message": fmt.Sprintf("合并后文件大小 %d 与申报大小 %d 不符", actualSize, info.FileSize),
			})
			return
		}
	}

	// 计算过期时间
	if err := utils.CheckExpireStyleAllowed(req.ExpireStyle); err != nil {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": err.Error(),
		})
		return
	}
	expireTime := utils.CalculateExpireTime(int(req.ExpireValue), req.ExpireStyle)
	expireCount := utils.CalculateExpireCount(req.ExpireStyle, int(req.ExpireValue))

	// 获取用户ID（如果有）
	var userID *uint
	if uid, exists := c.Get("user_id"); exists {
		if uidUint, ok := uid.(uint); ok {
			userID = &uidUint
		}
	}

	// 获取客户端 IP（可信代理解析）
	ownerIP := middleware.ClientIP(c)

	// 确定上传类型
	uploadType := "anonymous"
	if userID != nil {
		uploadType = "authenticated"
	}

	// 密码保护（修复 P0：此前 RequireAuth 透传但密码丢失，产出
	// require_auth=true 且哈希为空的死分享——取件侧对空哈希一律拒绝，
	// 分享永远无法取件）。密码经 form 字段传递（CompleteReq 模型无此字段）。
	passwordHash := ""
	if req.RequireAuth {
		password := c.DefaultPostForm("password", "")
		if password == "" {
			var pwBody struct {
				Password string `json:"password"`
			}
			if b := c.Request.Body(); len(b) > 0 {
				_ = json.Unmarshal(b, &pwBody)
				password = pwBody.Password
			}
		}
		if password == "" {
			c.JSON(consts.StatusBadRequest, map[string]interface{}{
				"code":    400,
				"message": "开启密码保护时必须提供密码",
			})
			return
		}
		hash, pwErr := utils.HashPassword(password)
		if pwErr != nil {
			c.JSON(consts.StatusInternalServerError, map[string]interface{}{
				"code":    500,
				"message": "密码处理失败",
			})
			return
		}
		passwordHash = hash
	}

	// 创建分享记录
	shareReq := &shareService.ShareFileReq{
		Channel:      "chunk",
		FilePath:     relativePath,
		Size:         info.FileSize,
		Text:         utils.SanitizeFileName(info.FileName),
		ExpiredAt:    expireTime,
		ExpiredCount: expireCount,
		RequireAuth:  req.RequireAuth,
		PasswordHash: passwordHash,
		UserID:       userID,
		UploadType:   uploadType,
		OwnerIP:      ownerIP,
		FileHash:     fileHash,
		IsChunked:    true,
		UploadID:     uploadID,
	}

	shareResult, err := getShareService().ShareFile(ctx, shareReq)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "创建分享记录失败: " + err.Error(),
		})
		return
	}

	// 更新上传状态为完成
	err = getChunkService().CompleteUpload(ctx, uploadID)
	if err != nil {
		// 记录错误但不影响返回结果
		fmt.Printf("更新上传状态失败: %v\n", err)
	}

	// 生成分享URL（附下载令牌，security.download_token.enabled 时必需）
	fullShareURL := fmt.Sprintf("%s/share/%s", defaultBaseURL, shareResult.Code)
	if tk := security.GenerateDownloadToken(shareResult.Code); tk != "" {
		fullShareURL += "?token=" + tk
	}

	resp := &chunkmodel.ChunkUploadCompleteResp{
		Code:    200,
		Message: "上传完成",
		Data: &chunkmodel.ChunkUploadCompleteData{
			ShareCode: shareResult.Code,
			ShareURL:  fullShareURL,
			FileName:  info.FileName,
			FileSize:  info.FileSize,
		},
	}

	c.JSON(consts.StatusOK, resp)
}

// readHeadFrom 从 reader 读取前 n 字节（魔数校验用）；读取失败返回 nil
func readHeadFrom(r io.Reader, n int) []byte {
	buf := make([]byte, n)
	read, err := io.ReadFull(r, buf)
	if err != nil && err != io.ErrUnexpectedEOF && err != io.EOF {
		return nil
	}
	return buf[:read]
}

// ChunkUploadCancel .
// @router /chunk/upload/cancel/:upload_id [DELETE]
func ChunkUploadCancel(ctx context.Context, c *app.RequestContext) {
	// 获取上传ID
	uploadID := c.Param("upload_id")
	if uploadID == "" {
		c.JSON(consts.StatusBadRequest, map[string]interface{}{
			"code":    400,
			"message": "上传ID不能为空",
		})
		return
	}

	// 删除分片存储
	err := getStorageService().CleanChunks(ctx, uploadID)
	if err != nil {
		fmt.Printf("清理分片文件失败: %v\n", err)
	}

	// 删除上传记录
	err = getChunkService().DeleteUpload(ctx, uploadID)
	if err != nil {
		c.JSON(consts.StatusInternalServerError, map[string]interface{}{
			"code":    500,
			"message": "取消上传失败: " + err.Error(),
		})
		return
	}

	resp := &chunkmodel.ChunkUploadCancelResp{
		Code:    200,
		Message: "上传已取消",
	}

	c.JSON(consts.StatusOK, resp)
}
